-- Add "Clothing" and "Machinery & Equipment" as new top-level categories.
--
-- 'clothing' already existed as a leaf under 'fashion-beauty', and 'industrial-machinery'
-- already existed as a leaf under 'business-industry'. Slugs are globally unique
-- (uk_category_slug), so rather than duplicate those concepts under new slugs, this migration
-- reparents the existing rows (same id/slug preserved) to their new top-level position instead
-- of inserting duplicates. 'shoes-footwear' and 'bags-accessories' are reparented the same way
-- since they were listed as Clothing's own children under 'fashion-beauty'. An "Agricultural
-- Machinery" child was intentionally NOT added under Machinery & Equipment because it duplicates
-- the existing 'agricultural-equipment' category under 'agriculture'.

-- New top-level category (Clothing is reparented below rather than inserted, since it already exists)

-- Reparent pre-existing categories to their new top-level position
UPDATE categories SET parent_id = NULL, display_order = 160 WHERE slug = 'clothing' AND parent_id IS NOT NULL;
UPDATE categories SET parent_id = (SELECT id FROM categories WHERE slug = 'clothing'), display_order = 40 WHERE slug = 'shoes-footwear';
UPDATE categories SET parent_id = (SELECT id FROM categories WHERE slug = 'clothing'), display_order = 50 WHERE slug = 'bags-accessories';
UPDATE categories SET parent_id = (SELECT id FROM categories WHERE slug = 'machinery-equipment'), display_order = 10 WHERE slug = 'industrial-machinery';

